import * as z from "zod/v4";
import { defineChannel, localDevStrict, POST } from "../../channels.js";
import { skipped, tagOutcome } from "../../internal/channel-dispatch.js";
import { deploymentEventMatches, resolveDeploymentSubscriptions, } from "../../internal/cursor-deployment-relay.js";
import { attachHostedAdmissionAdapter } from "../../internal/hosted-admission-adapter.js";
import { bindLocalIngressSend } from "../../internal/local-ingress.js";
import { DEPLOYMENT_EVENT_TYPES, DEPLOYMENTS_CHANNEL_KIND, } from "./types.js";
const deploymentEventSchema = z.object({
    eventType: z.enum(DEPLOYMENT_EVENT_TYPES),
    eventId: z.string().min(1),
    teamId: z.number(),
    deploySourceUri: z.string().min(1),
    deploymentId: z.string().min(1),
    environment: z.string().min(1),
    service: z.string().min(1).optional(),
    deployVersion: z.string().min(1),
    previousVersion: z.string().min(1).optional(),
    status: z.enum(["pending", "in_progress", "success", "failed"]),
    occurredAtMs: z.number(),
});
/** Options used to construct a deployments channel — for host-level fan-out. */
const deploymentsChannelOptionsByDefinition = new WeakMap();
/**
 * Recover the {@link DeploymentsChannelOptions} used to build a channel
 * definition, if it was created via {@link deploymentsChannel}.
 */
export function getDeploymentsChannelOptions(definition) {
    return deploymentsChannelOptionsByDefinition.get(definition);
}
/**
 * Events a {@link deploymentsChannel} dispatches on, unioned from its
 * subscriptions. Published as `meta.deploymentEventTypes` so the deploy
 * manifest can extract `eventTypes`.
 *
 * A channel with no resolved subscriptions declares the full event set.
 * That covers an omitted `deploySourceUris` and the env-configured case:
 * the hosted freeze bakes hermetically (no customer env/secrets), so
 * deriving `[]` there would leave the manifest without event types and no
 * subscription edge could ever materialize (invariant 26). Capability is
 * the channel's code shape — `onEvent` handles any deployment event —
 * while sources/environments/event narrowing are runtime subscription
 * config; the hosted-admission adapter re-applies them before authored
 * code runs. Inertness is still guaranteed by scope: a deploy that names
 * no repositories binds no edges.
 */
export function deriveDeploymentEventTypes(options) {
    const subscriptions = resolveDeploymentSubscriptions(options);
    if (subscriptions.length === 0) {
        return [...DEPLOYMENT_EVENT_TYPES].sort();
    }
    const events = new Set();
    for (const subscription of subscriptions) {
        for (const event of subscription.events) {
            events.add(event);
        }
    }
    return [...events].sort();
}
/**
 * Core deployment-event dispatch, used by the channel's replay route, the
 * serve host's relay fan-out, and the hosted-admission adapter. Whether the
 * event matches this channel's subscriptions is the caller's decision.
 */
export async function dispatchDeploymentEvent(input) {
    await input.options.onEvent(input.event, bindLocalIngressSend(input.args, {
        identity: input.options.continuation,
        kind: DEPLOYMENTS_CHANNEL_KIND,
        eventType: input.event.eventType,
        payload: input.event,
    }));
    // "task": authored `onEvent` ran to completion without a captured send.
    // Hosted admission only consults this when no send was captured.
    return tagOutcome(Response.json({ ok: true }), "task");
}
/**
 * Whether this channel admits the event on a hosted pod. The hosted
 * control plane fans out on `(deploy_source, eventType, team)` edges only —
 * environments are not edge identity — so this is where the environment
 * filter (and a stale-edge guard for sources/events) lives, mirroring what
 * the v1 relay does before `onEvent`.
 *
 * A channel with NO resolved subscriptions admits everything the control
 * plane delivered. Omitting `deploySourceUris` picks that deliberately:
 * the deploy-time edges (bound from the watched repositories) already
 * carry the tenant's scope, so re-filtering here could only narrow it with
 * another tenant's list. The same holds for an env-configured channel that
 * resolves empty on a restored pod, where refusing would silently drop
 * every delivery. Same rule as {@link deriveDeploymentEventTypes}:
 * authored subscriptions narrow; a channel that names none defers to the
 * deploy scope.
 */
export function deploymentEventMatchesChannel(options, event) {
    const subscriptions = resolveDeploymentSubscriptions(options);
    if (subscriptions.length === 0) {
        return true;
    }
    return subscriptions.some((subscription) => subscription.deploySourceUri === event.deploySourceUri.toLowerCase() &&
        deploymentEventMatches(subscription, event));
}
/**
 * Deployment events channel.
 *
 * ```ts
 * import { deploymentsChannel } from "@grok/agent-sdk/channels/deployments";
 *
 * export default deploymentsChannel({
 *   deploySourceUris: ["https://origin.cursor.com/repos/anysphere/everysphere"],
 *   environments: ["prod"],
 *   onEvent: async (event, { send }) => {
 *     await send(`${event.deploySourceUri}@${event.deployVersion} shipped to ${event.environment}`);
 *   },
 * });
 * ```
 *
 * Declarative: the channel names what it wants and handles what arrives. The
 * serve host discovers every mounted deployments channel, opens one
 * `/v0/deployment-events` relay for the process, and routes each event to the
 * channels subscribed to it — the same ownership the Slack and SCM relays
 * have. Nothing is pushed to this deployment and no shared secret exists on
 * either side.
 *
 * Hosted v2 deployments do not poll: the control plane fans verified factory
 * deployment events out on `deploy_source` subscription edges — derived from
 * the deploy's watched `repositories`, since factory records deploy sources
 * as Origin repo URLs — and delivers through hosted admission. The attached
 * adapter re-applies this channel's subscription filter — environments are
 * not edge identity — and skips before authored code runs.
 *
 * A hosted agent therefore omits `deploySourceUris`:
 *
 * ```ts
 * export default deploymentsChannel({
 *   events: ["deployment.created", "deployment.succeeded"],
 *   onEvent: async (event, { send }) => { ... },
 * });
 * ```
 *
 * The route on this channel exists for local replay (`agent-sdk` and tests):
 * POST an event body and it runs the same `onEvent`.
 */
export function deploymentsChannel(options) {
    // Throws here rather than at startup, so a malformed `deploySourceUris`
    // entry fails when the channel module is authored instead of when the host
    // mounts it.
    resolveDeploymentSubscriptions(options);
    const routePath = options.path ?? "/";
    const definition = defineChannel({
        auth: options.auth ?? [localDevStrict()],
        meta: {
            kind: DEPLOYMENTS_CHANNEL_KIND,
            deploymentEventTypes: deriveDeploymentEventTypes(options),
        },
        ...(options.onStart === undefined ? {} : { onStart: options.onStart }),
        ...(options.onStop === undefined ? {} : { onStop: options.onStop }),
        routes: [
            POST(routePath, {
                description: "Replay one deployment event onto this channel",
                bodySchema: deploymentEventSchema,
                handler: async (_request, args) => dispatchDeploymentEvent({
                    options,
                    event: args.body,
                    args,
                }),
            }),
        ],
    });
    deploymentsChannelOptionsByDefinition.set(definition, options);
    // Hosted v2 delivery: the control plane admits a deployments mailbox item
    // (deploy_source edge match) and posts the claim-checked factory envelope
    // here. Environments are not edge identity, so non-matching environments
    // (and stale-edge sources/events) are filtered to `skip` before authored
    // code runs — the same pre-`onEvent` filter the v1 relay applies.
    attachHostedAdmissionAdapter(definition, {
        kind: DEPLOYMENTS_CHANNEL_KIND,
        dispatch: async ({ payload, args }) => {
            const parsed = deploymentEventSchema.safeParse(payload);
            if (!parsed.success) {
                return Response.json({ ok: false, error: "invalid_deployment_event" }, { status: 400 });
            }
            const event = parsed.data;
            if (!deploymentEventMatchesChannel(options, event)) {
                return skipped("subscription_mismatch");
            }
            return dispatchDeploymentEvent({ options, event, args });
        },
    });
    return definition;
}
